Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await MetadataGod.initialize();

  // Read metadata
  Metadata metadata = await MetadataGod.readMetadata('/path/to/audio-file.mp3');
  print(metadata.title);

  // Write metadata
  await MetadataGod.writeMetadata(
    '/path/to/audio-file.mp3',
    Metadata(
      title: 'Song Title',
      artist: 'Artist Name',
      album: 'Album Name',
      year: 2024,
    ),
  );
}
